<?php
session_start();if(empty($_SESSION['admin_ok'])){header('Location: admin.php');exit;}function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$user=(string)($_SESSION['admin_user']??'');$role=(string)($_SESSION['admin_role']??'user');$file=__DIR__.'/data/orcamentos.json';$all=is_file($file)?json_decode((string)file_get_contents($file),true):[];if(!is_array($all))$all=[];$mine=array_values(array_filter($all,fn($q)=>strcasecmp((string)($q['user']??''),$user)===0));
function qt($q){$t=0;foreach(($q['items']??[])as$i)if(is_numeric($i['price']??null))$t+=(float)$i['price']*(int)($i['qty']??1);return $t*(1-max(0,min(100,(float)($q['discount']??0)))/100);}
$month=date('Y-m');$m=array_values(array_filter($mine,fn($q)=>str_starts_with((string)($q['created_at']??''),$month)));$value=array_sum(array_map('qt',$m));$approved=count(array_filter($m,fn($q)=>($q['status']??'rascunho')==='aprovado'));$neg=count(array_filter($mine,fn($q)=>in_array(($q['status']??'rascunho'),['enviado','negociacao'],true)));$conv=count($m)?round($approved/count($m)*100,1):0;$today=date('Y-m-d');$returns=array_values(array_filter($mine,fn($q)=>($d=$q['commercial']['return_date']??'')!==''&&$d<=$today&&!in_array(($q['status']??''),['aprovado','perdido','cancelado'],true)));usort($mine,fn($a,$b)=>strcmp($b['updated_at']??'',$a['updated_at']??''));
$labels=['rascunho'=>'Rascunho','enviado'=>'Enviado','negociacao'=>'Em negociação','aprovado'=>'Aprovado','perdido'=>'Perdido','cancelado'=>'Cancelado'];
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Meu painel — ELEDS</title><link rel="stylesheet" href="assets/css/style.css?v=20261002-layoutfix1"></head><body class="admin-page"><header class="admin-header"><div class="container admin-header-inner"><a href="index.php" class="logo logo-image"><img src="assets/eleds-logo.png" alt="ELEDS"></a><div class="admin-actions"><span class="admin-user-chip"><?php if(strcasecmp((string)($_SESSION['admin_user'] ?? ''), 'admin') === 0): ?><img src="assets/eleds-aguia-avatar.png" alt="Águia ELEDS"><?php elseif(!empty($_SESSION['admin_photo'])): ?><img src="<?=e($_SESSION['admin_photo'])?>" alt="Foto"><?php else: ?>👤<?php endif; ?> <strong><?=e($user)?></strong></span><a href="orcamentos.php">Meus orçamentos</a><?php if($role==='admin'):?><a href="admin.php">Administração</a><?php endif;?><a href="index.php">Catálogo</a><a href="admin.php?logout=1">Sair</a></div></div></header><main class="container admin-main"><div class="admin-title"><div><span class="section-kicker">PAINEL DO CONSULTOR</span><h1>Olá, <?=e($user)?> 👋</h1><p>Resumo comercial dos seus orçamentos.</p></div><a class="admin-primary" href="index.php">+ Novo orçamento</a></div>
<div class="crm-cards"><div><small>Orçamentos no mês</small><b><?=count($m)?></b></div><div><small>Valor orçado no mês</small><b>R$ <?=number_format($value,2,',','.')?></b></div><div><small>Aprovados no mês</small><b><?=$approved?></b></div><div><small>Em acompanhamento</small><b><?=$neg?></b></div><div><small>Conversão</small><b><?=$conv?>%</b></div></div>
<?php if($returns):?><section class="admin-panel crm-alert"><h3>📅 Retornos que precisam de atenção</h3><?php foreach(array_slice($returns,0,6) as$q):?><p><strong><?=e($q['number']??$q['id'])?></strong> — <?=e($q['customer']['name']??'Cliente não informado')?> · retorno <?=e(date('d/m/Y',strtotime($q['commercial']['return_date'])))?> <a href="index.php?orcamento=<?=urlencode($q['id'])?>">Abrir</a></p><?php endforeach;?></section><?php endif;?>
<section class="admin-panel"><h3>Últimos orçamentos</h3><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Número</th><th>Cliente</th><th>Status</th><th>Total</th><th>Atualizado</th><th></th></tr></thead><tbody><?php if(!$mine):?><tr><td colspan="6">Nenhum orçamento salvo.</td></tr><?php endif;?><?php foreach(array_slice($mine,0,8) as$q):?><tr><td><strong><?=e($q['number']??$q['id'])?></strong></td><td><?=e($q['customer']['name']??($q['note']??'Sem identificação'))?></td><td><span class="crm-status s-<?=e($q['status']??'rascunho')?>"><?=e($labels[$q['status']??'rascunho']??'Rascunho')?></span></td><td>R$ <?=number_format(qt($q),2,',','.')?></td><td><?=e(date('d/m/Y H:i',strtotime($q['updated_at']??'now')))?></td><td><a href="index.php?orcamento=<?=urlencode($q['id'])?>">Continuar</a></td></tr><?php endforeach;?></tbody></table></div><p><a href="orcamentos.php">Ver todos os meus orçamentos →</a></p></section></main></body></html>
